import { useState, useMemo, useRef, useEffect, useCallback, useLayoutEffect } from 'react'
import { createPortal } from 'react-dom'
import {
  Plus,
  Search,
  Trash2,
  FolderPlus,
  ChevronRight,
  ChevronDown,
  Edit2,
  Copy,
  SortAsc,
  SortDesc,
  Folder,
  FolderOpen,
  X
} from 'lucide-react'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useUIStore } from '@/store/useUIStore'
import { useCanvasStore } from '@/store/useCanvasStore'
import clsx from 'clsx'
import type { NodeCard, NodePoolFolder, NodePoolSortOption, NodePoolSortOrder } from '@/types'

interface NodePoolPanelProps {
  open: boolean
}

interface ContextMenuState {
  x: number
  y: number
  card: NodeCard | null
  folder: NodePoolFolder | null
}

export function NodePoolPanel({ open }: NodePoolPanelProps) {
  const {
    nodePool,
    nodePoolFolders,
    nodePoolSortBy,
    nodePoolSortOrder,
    addToNodePool,
    removeFromNodePool,
    updateNodeCard,
    incrementNodeCardUseCount,
    setNodePoolSortBy,
    setNodePoolSortOrder,
    createNodePoolFolder,
    updateNodePoolFolder,
    deleteNodePoolFolder,
    toggleNodePoolFolderCollapsed,
  } = useProjectsStore()
  const { selectedIds, addNode } = useCanvasStore()
  const { addToast } = useUIStore()
  const [searchQuery, setSearchQuery] = useState('')
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null)
  const [editingFolder, setEditingFolder] = useState<NodePoolFolder | null>(null)
  const [editingCardId, setEditingCardId] = useState<number | null>(null)
  const [newFolderName, setNewFolderName] = useState('')
  const [showNewFolderInput, setShowNewFolderInput] = useState(false)
  const [draggedCard, setDraggedCard] = useState<NodeCard | null>(null)
  const [dragOverFolderId, setDragOverFolderId] = useState<number | null>(null)
  const [dragOverRoot, setDragOverRoot] = useState(false)
  const panelRef = useRef<HTMLDivElement>(null)

  // Sort and filter node pool
  const sortedAndFilteredPool = useMemo(() => {
    let filtered = nodePool.filter((card) =>
      card.name.toLowerCase().includes(searchQuery.toLowerCase())
    )

    filtered.sort((a, b) => {
      let comparison = 0
      switch (nodePoolSortBy) {
        case 'name':
          comparison = a.name.localeCompare(b.name)
          break
        case 'createdAt':
          comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
          break
        case 'useCount':
          comparison = a.useCount - b.useCount
          break
      }
      return nodePoolSortOrder === 'asc' ? comparison : -comparison
    })

    return filtered
  }, [nodePool, searchQuery, nodePoolSortBy, nodePoolSortOrder])

  // Group cards by folder
  const { rootCards, folderCards } = useMemo(() => {
    const root: NodeCard[] = []
    const byFolder: Record<number, NodeCard[]> = {}

    sortedAndFilteredPool.forEach((card) => {
      if (card.folderId) {
        if (!byFolder[card.folderId]) {
          byFolder[card.folderId] = []
        }
        byFolder[card.folderId].push(card)
      } else {
        root.push(card)
      }
    })

    return { rootCards: root, folderCards: byFolder }
  }, [sortedAndFilteredPool])

  // Build folder tree
  const folderTree = useMemo(() => {
    const buildTree = (parentId: number | null): NodePoolFolder[] => {
      return nodePoolFolders
        .filter((f) => f.parentId === parentId)
        .map((folder) => ({
          ...folder,
          children: buildTree(folder.id),
        }))
    }
    return buildTree(null)
  }, [nodePoolFolders])

  // Render folder with cards
  const renderFolder = (folder: NodePoolFolder & { children?: NodePoolFolder[] }, level = 0) => {
    const cards = folderCards[folder.id] || []
    const isCollapsed = folder.collapsed
    const isDragOver = dragOverFolderId === folder.id

    return (
      <div key={folder.id} className="mb-2">
        <div
          className={clsx(
            'flex items-center gap-1 px-2 py-1.5 rounded-lg cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors',
            editingFolder?.id === folder.id && 'bg-blue-50 dark:bg-blue-900/20',
            isDragOver && 'bg-blue-100 dark:bg-blue-900/40 ring-2 ring-blue-400'
          )}
          onClick={() => toggleNodePoolFolderCollapsed(folder.id)}
          onContextMenu={(e) => handleFolderContextMenu(e, folder)}
          onDragOver={(e) => handleDragOverFolder(e, folder.id)}
          onDragLeave={(e) => {
            e.preventDefault()
            e.stopPropagation()
            setDragOverFolderId(null)
          }}
          onDrop={(e) => handleDropOnFolder(e, folder.id)}
        >
          {folder.children && (folder.children.length > 0 || cards.length > 0) ? (
            isCollapsed ? (
              <ChevronRight className="w-3.5 h-3.5 text-gray-500" />
            ) : (
              <ChevronDown className="w-3.5 h-3.5 text-gray-500" />
            )
          ) : (
            <div className="w-3.5 h-3.5" />
          )}
          {isCollapsed ? (
            <Folder className="w-4 h-4 text-gray-400 dark:text-gray-500" />
          ) : (
            <FolderOpen className="w-4 h-4 text-blue-500 shadow-sm" />
          )}
          <span className="text-sm font-medium text-gray-700 dark:text-gray-300 flex-1">
            {editingFolder?.id === folder.id ? (
              <input
                type="text"
                defaultValue={folder.name}
                autoFocus
                className="w-full bg-transparent border-b border-blue-500 outline-none"
                onBlur={(e) => handleSaveFolderName(folder.id, e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleSaveFolderName(folder.id, e.currentTarget.value)
                  } else if (e.key === 'Escape') {
                    setEditingFolder(null)
                  }
                }}
                onClick={(e) => e.stopPropagation()}
              />
            ) : (
              folder.name
            )}
          </span>
          <span className="text-xs text-gray-500 dark:text-gray-400">
            {cards.length}
          </span>
        </div>

        {!isCollapsed && (
          <div className="ml-[18px] pl-3 border-l border-gray-100 dark:border-gray-700/50 my-1 space-y-1">
            {cards.map((card) => (
              <div key={card.id} className="py-0.5">
                <NodeCardItem
                  card={card}
                  onUse={handleUseCard}
                  onRemove={() => handleRemoveFromPool(card.id)}
                  onSave={handleSaveCardName}
                  onContextMenu={(e) => handleCardContextMenu(e, card)}
                  onDragStart={() => handleDragStart(card)}
                  onDragEnd={handleDragEnd}
                  externalEditing={editingCardId === card.id}
                  onExternalEditEnd={() => setEditingCardId(null)}
                />
              </div>
            ))}

            {folder.children && folder.children.map((child) => renderFolder(child, level + 1))}
          </div>
        )}
      </div>
    )
  }

  // Handle add selected node to pool
  const handleAddToPool = async () => {
    if (selectedIds.length === 0) {
      addToast({ type: 'warning', title: '未选择节点', message: '请选择一个节点添加到节点池' })
      return
    }

    const nodeId = selectedIds[0]
    const currentProject = useProjectsStore.getState().currentProject
    if (!currentProject) {
      addToast({ type: 'warning', title: '未选择项目', message: '请先选择一个项目' })
      return
    }

    const nodes = useCanvasStore.getState().nodes
    const node = nodes.get(nodeId)
    if (!node) return

    try {
      await addToNodePool(currentProject.id, {
        projectId: currentProject.id,
        name: node.title || node.content || '未命名',
        content: JSON.stringify(node),
        type: node.type || 'text',
        color: node.color,
        tags: null,
        createdBy: 1,
      })
      addToast({ type: 'success', title: '已添加到节点池', message: '节点已添加到节点池' })
    } catch (error) {
      addToast({ type: 'error', title: '添加失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  // Handle use card from pool (Consumes the card: adds to canvas and removes from pool)
  const handleUseCard = async (card: NodeCard) => {
    try {
      const nodeData = JSON.parse(card.content)
      const newNode = {
        ...nodeData,
        id: `${nodeData.id}-pool-${Date.now()}`,
        x: nodeData.x + 50,
        y: nodeData.y + 50,
      }
      addNode(newNode)

      // Remove from pool immediately as it's "consumed"
      await removeFromNodePool(card.id)
      addToast({ type: 'success', title: '节点已取出', message: '卡片已从池中取出到画布' })
    } catch (error) {
      addToast({ type: 'error', title: '使用节点失败', message: '无法解析节点数据' })
    }
  }

  // Handle remove from pool
  const handleRemoveFromPool = async (id: number) => {
    try {
      await removeFromNodePool(id)
      addToast({ type: 'success', title: '已从节点池移除', message: '节点已从节点池移除' })
    } catch (error) {
      addToast({ type: 'error', title: '移除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  // Handle save card name
  const handleSaveCardName = async (card: NodeCard, name: string) => {
    try {
      await updateNodeCard(card.id, { name })
      addToast({ type: 'success', title: '已更新', message: '节点卡片名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '更新失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  // Handle card context menu
  const handleCardContextMenu = (e: React.MouseEvent, card: NodeCard) => {
    e.preventDefault()
    e.stopPropagation()
    setContextMenu({ x: e.clientX, y: e.clientY, card, folder: null })
  }

  // Handle folder context menu
  const handleFolderContextMenu = (e: React.MouseEvent, folder: NodePoolFolder) => {
    e.preventDefault()
    e.stopPropagation()
    setContextMenu({ x: e.clientX, y: e.clientY, card: null, folder })
  }

  // Handle create folder
  const handleCreateFolder = async () => {
    const currentProject = useProjectsStore.getState().currentProject
    if (!currentProject) {
      addToast({ type: 'warning', title: '未选择项目', message: '请先选择一个项目' })
      return
    }

    if (!newFolderName.trim()) {
      addToast({ type: 'warning', title: '请输入文件夹名称', message: '文件夹名称不能为空' })
      return
    }

    try {
      await createNodePoolFolder(currentProject.id, {
        projectId: currentProject.id,
        name: newFolderName.trim(),
        parentId: null,
        sortOrder: 0,
        collapsed: false,
      })
      setNewFolderName('')
      setShowNewFolderInput(false)
      addToast({ type: 'success', title: '已创建', message: '文件夹已创建' })
    } catch (error) {
      addToast({ type: 'error', title: '创建失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  // Handle save folder name
  const handleSaveFolderName = async (id: number, name: string) => {
    try {
      await updateNodePoolFolder(id, { name })
      addToast({ type: 'success', title: '已更新', message: '文件夹名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '更新失败', message: error instanceof Error ? error.message : '未知错误' })
    }
    setEditingFolder(null)
  }

  // Handle sort change
  const handleSortChange = (sortBy: NodePoolSortOption) => {
    if (nodePoolSortBy === sortBy) {
      setNodePoolSortOrder(nodePoolSortOrder === 'asc' ? 'desc' : 'asc')
    } else {
      setNodePoolSortBy(sortBy)
      setNodePoolSortOrder('desc')
    }
  }

  // Drag and drop handlers
  const handleDragStart = (card: NodeCard) => {
    setDraggedCard(card)
  }

  const handleDragEnd = () => {
    setDraggedCard(null)
    setDragOverFolderId(null)
    setDragOverRoot(false)
  }

  // Handle dragging over folder
  const handleDragOverFolder = (e: React.DragEvent, folderId: number) => {
    e.preventDefault()
    e.stopPropagation()
    if (draggedCard) {
      setDragOverFolderId(folderId)
    }
  }

  // Handle dragging over root area
  const handleDragOverRoot = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (draggedCard) {
      setDragOverRoot(true)
    }
  }

  // Handle drop on folder
  const handleDropOnFolder = async (e: React.DragEvent, folderId: number) => {
    e.preventDefault()
    e.stopPropagation()
    setDragOverFolderId(null)

    if (draggedCard && draggedCard.folderId !== folderId) {
      try {
        await updateNodeCard(draggedCard.id, { folderId })
        addToast({ type: 'success', title: '已移动', message: '节点卡片已移动到文件夹' })
      } catch (error) {
        addToast({ type: 'error', title: '移动失败', message: error instanceof Error ? error.message : '未知错误' })
      }
    }
    setDraggedCard(null)
  }

  // Handle drop on root (remove from folder)
  const handleDropOnRoot = async (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setDragOverRoot(false)

    if (draggedCard && draggedCard.folderId !== null) {
      try {
        await updateNodeCard(draggedCard.id, { folderId: null })
        addToast({ type: 'success', title: '已移动', message: '节点卡片已移动到根目录' })
      } catch (error) {
        addToast({ type: 'error', title: '移动失败', message: error instanceof Error ? error.message : '未知错误' })
      }
    }
    setDraggedCard(null)
  }

  const handleDropOnCanvas = async (e: React.DragEvent) => {
    e.preventDefault()
    if (draggedCard) {
      // Calculate position relative to canvas
      const rect = (e.target as HTMLElement).getBoundingClientRect()
      const x = e.clientX - rect.left
      const y = e.clientY - rect.top

      try {
        const nodeData = JSON.parse(draggedCard.content)
        addNode({
          ...nodeData,
          id: `${nodeData.id}-pool-${Date.now()}`,
          x,
          y,
        })
        // Remove from pool immediately as it's "consumed"
        await removeFromNodePool(draggedCard.id)
        addToast({ type: 'success', title: '节点已取出', message: '卡片已从池中取出到画布' })
      } catch (error) {
        addToast({ type: 'error', title: '使用节点失败', message: '无法解析节点数据' })
      }
    }
    // Logic here is mostly a fallback as CanvasPage.tsx also handles dropping
    // Clean up local drag state
    setDraggedCard(null)
    setDragOverFolderId(null)
    setDragOverRoot(false)
  }

  // Close context menu on click outside
  const handleClickOutside = () => {
    setContextMenu(null)
  }

  // Context menu actions
  const contextMenuActions = useMemo(() => {
    if (!contextMenu) return []

    const actions: Array<{
      label: string
      icon: React.ElementType
      action: () => void
      danger?: boolean
    }> = []

    if (contextMenu.card) {
      actions.push(
        {
          label: '复制到画布',
          icon: Copy,
          action: () => {
            const card = contextMenu.card!
            try {
              const nodeData = JSON.parse(card.content)
              addNode({
                ...nodeData,
                id: `${nodeData.id}-pool-copy-${Date.now()}`,
                x: nodeData.x + 100,
                y: nodeData.y + 100,
              })
              addToast({ type: 'success', title: '已复制', message: '节点已复制到画布，保留在池中' })
            } catch (error) {
              addToast({ type: 'error', title: '复制失败', message: '无法解析节点数据' })
            }
            setContextMenu(null)
          },
        },
        {
          label: '删除',
          icon: Trash2,
          action: () => {
            handleRemoveFromPool(contextMenu.card!.id)
            setContextMenu(null)
          },
          danger: true,
        }
      )
    }

    if (contextMenu.folder) {
      actions.push(
        {
          label: '重命名',
          icon: Edit2,
          action: () => {
            setEditingFolder(contextMenu.folder!)
            setContextMenu(null)
          },
        },
        {
          label: '删除',
          icon: Trash2,
          action: async () => {
            await deleteNodePoolFolder(contextMenu.folder!.id)
            addToast({ type: 'success', title: '已删除', message: '文件夹已删除' })
            setContextMenu(null)
          },
          danger: true,
        }
      )
    }

    return actions
  }, [contextMenu])

  return (
    <aside
      ref={panelRef}
      className={clsx(
        'bg-white dark:bg-gray-800 border-l border-gray-200 dark:border-gray-700 flex flex-col transition-all duration-200',
        open ? 'w-72' : 'w-0'
      )}
      onClick={handleClickOutside}
    >
      {/* Header */}
      <div className="h-12 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between px-4 flex-shrink-0">
        <h2 className="font-semibold text-gray-800 dark:text-white">节点池</h2>
        <div className="flex items-center gap-1">
          <button
            onClick={() => setShowNewFolderInput(!showNewFolderInput)}
            className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
            title="新建文件夹"
          >
            <FolderPlus className="w-4 h-4" />
          </button>
          <button
            onClick={handleAddToPool}
            className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
            title="添加选中节点到池 (Ctrl+Shift+A)"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* New folder input */}
      {showNewFolderInput && (
        <div className="p-3 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="文件夹名称..."
              value={newFolderName}
              onChange={(e) => setNewFolderName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleCreateFolder()
                else if (e.key === 'Escape') setShowNewFolderInput(false)
              }}
              className="flex-1 px-2 py-1 text-sm bg-gray-100 dark:bg-gray-700 border-0 rounded focus:ring-2 focus:ring-blue-500 text-gray-800 dark:text-white"
              autoFocus
            />
            <button
              onClick={handleCreateFolder}
              className="px-3 py-1 text-sm bg-blue-500 text-white rounded hover:bg-blue-600"
            >
              创建
            </button>
            <button
              onClick={() => setShowNewFolderInput(false)}
              className="p-1 text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Search and Sort */}
      <div className="p-3 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
        <div className="relative mb-2">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="搜索节点..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm bg-gray-100 dark:bg-gray-700 border-0 rounded-lg focus:ring-2 focus:ring-blue-500 text-gray-800 dark:text-white placeholder-gray-500"
          />
        </div>

        {/* Sort buttons */}
        <div className="flex gap-1">
          <button
            onClick={() => handleSortChange('name')}
            className={clsx(
              'flex-1 px-2 py-1 text-xs rounded flex items-center justify-center gap-1',
              nodePoolSortBy === 'name'
                ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
            )}
          >
            名称
            {nodePoolSortBy === 'name' && (
              nodePoolSortOrder === 'asc' ? <SortAsc className="w-3 h-3" /> : <SortDesc className="w-3 h-3" />
            )}
          </button>
          <button
            onClick={() => handleSortChange('createdAt')}
            className={clsx(
              'flex-1 px-2 py-1 text-xs rounded flex items-center justify-center gap-1',
              nodePoolSortBy === 'createdAt'
                ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
            )}
          >
            创建时间
            {nodePoolSortBy === 'createdAt' && (
              nodePoolSortOrder === 'asc' ? <SortAsc className="w-3 h-3" /> : <SortDesc className="w-3 h-3" />
            )}
          </button>
        </div>
      </div>

      {/* Node Cards */}
      <div
        className={clsx(
          'flex-1 overflow-y-auto custom-scrollbar p-3 transition-colors',
          dragOverRoot && 'bg-blue-50 dark:bg-blue-900/20'
        )}
        onDragOver={handleDragOverRoot}
        onDragLeave={(e) => {
          e.preventDefault()
          setDragOverRoot(false)
        }}
        onDrop={handleDropOnRoot}
      >
        {/* Render folder tree */}
        {folderTree.map((folder) => renderFolder(folder))}

        {/* Root cards */}
        {rootCards.map((card) => (
          <div key={card.id} className="mb-2">
            <NodeCardItem
              card={card}
              onUse={handleUseCard}
              onRemove={() => handleRemoveFromPool(card.id)}
              onSave={handleSaveCardName}
              onContextMenu={(e) => handleCardContextMenu(e, card)}
              onDragStart={() => handleDragStart(card)}
              onDragEnd={handleDragEnd}
              externalEditing={editingCardId === card.id}
              onExternalEditEnd={() => setEditingCardId(null)}
            />
          </div>
        ))}

        {/* Empty state */}
        {sortedAndFilteredPool.length === 0 && (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            <p className="text-sm">节点池为空</p>
            <p className="text-xs mt-1">选择节点并点击 + 添加</p>
          </div>
        )}
      </div>

      {/* Context Menu */}
      {contextMenu && (
        <div
          className="fixed z-50 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 min-w-40"
          style={{ left: contextMenu.x, top: contextMenu.y }}
          onClick={(e) => e.stopPropagation()}
        >
          {contextMenuActions.map((action, index) => (
            <button
              key={index}
              onClick={action.action}
              className={clsx(
                'w-full px-4 py-2 text-left text-sm flex items-center gap-2 hover:bg-gray-100 dark:hover:bg-gray-700',
                action.danger
                  ? 'text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20'
                  : 'text-gray-700 dark:text-gray-300'
              )}
            >
              <action.icon className="w-4 h-4" />
              {action.label}
            </button>
          ))}
        </div>
      )}
    </aside>
  )
}

function NodeCardItem({
  card,
  onUse,
  onRemove,
  onSave,
  onContextMenu,
  onDragStart,
  onDragEnd,
  externalEditing,
  onExternalEditEnd,
}: {
  card: NodeCard
  onUse: (card: NodeCard) => void
  onRemove: () => void
  onSave: (card: NodeCard, name: string) => void
  onContextMenu: (e: React.MouseEvent) => void
  onDragStart: (card: NodeCard) => void
  onDragEnd: () => void
  externalEditing?: boolean
  onExternalEditEnd?: () => void
}) {
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(card.name)
  const [showPreview, setShowPreview] = useState(false)
  const [previewPosition, setPreviewPosition] = useState({ x: 0, y: 0 })
  const cardRef = useRef<HTMLDivElement>(null)

  // Handle external editing trigger
  useEffect(() => {
    if (externalEditing) {
      setIsEditing(true)
    }
  }, [externalEditing])

  const handleSave = async () => {
    if (editName.trim() && editName.trim() !== card.name) {
      await onSave(card, editName.trim())
    }
    setIsEditing(false)
    setEditName(card.name)
    onExternalEditEnd?.()
  }

  const handleCancel = () => {
    setIsEditing(false)
    setEditName(card.name)
    onExternalEditEnd?.()
  }

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.effectAllowed = 'copy'
    e.dataTransfer.setData('application/nodepool-card', JSON.stringify(card))
    onDragStart(card)
  }

  const handleMouseEnter = (e: React.MouseEvent) => {
    const cardElement = e.currentTarget as HTMLElement
    const cardRect = cardElement.getBoundingClientRect()

    // 查找节点池面板元素
    const panelElement = cardElement.closest('aside') as HTMLElement
    const panelRect = panelElement?.getBoundingClientRect()
    const panelLeft = panelRect?.left || 0

    setPreviewPosition({
      x: panelLeft,
      y: cardRect.top
    })
    setShowPreview(true)
  }

  const handleMouseMove = (e: React.MouseEvent) => {
    if (showPreview && cardRef.current) {
      const cardRect = cardRef.current.getBoundingClientRect()

      // 查找节点池面板元素
      const panelElement = cardRef.current.closest('aside') as HTMLElement
      const panelRect = panelElement?.getBoundingClientRect()
      const panelLeft = panelRect?.left || 0

      setPreviewPosition({
        x: panelLeft,
        y: cardRect.top
      })
    }
  }

  // Parse card content
  const parseCardContent = useCallback(() => {
    try {
      const nodeData = JSON.parse(card.content)
      return {
        type: nodeData.type || 'text',
        title: nodeData.title || card.name,
        content: nodeData.content || '',
        imageUrl: nodeData.imageUrl || null,
        color: nodeData.color || card.color
      }
    } catch {
      return {
        type: 'text',
        title: card.name,
        content: card.content,
        imageUrl: null,
        color: card.color
      }
    }
  }, [card])

  return (
    <div
      ref={cardRef}
      draggable
      onDragStart={handleDragStart}
      onDragEnd={onDragEnd}
      className="p-3 rounded-lg border border-gray-200 dark:border-gray-700 hover:border-blue-400 dark:hover:border-blue-500 cursor-pointer group relative transition-all duration-200 hover:shadow-md"
      onClick={() => onUse(card)}
      onContextMenu={onContextMenu}
      onMouseEnter={handleMouseEnter}
      onMouseMove={handleMouseMove}
      onMouseLeave={() => setShowPreview(false)}
      style={{ backgroundColor: card.color || '#ffffff' }}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1 min-w-0">
          {isEditing ? (
            <input
              type="text"
              value={editName}
              onChange={(e) => setEditName(e.target.value)}
              onBlur={handleSave}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault()
                  handleSave()
                } else if (e.key === 'Escape') {
                  e.preventDefault()
                  handleCancel()
                }
              }}
              className="w-full px-1 py-0.5 text-sm bg-white dark:bg-gray-800 border border-blue-500 rounded outline-none"
              autoFocus
              onClick={(e) => e.stopPropagation()}
            />
          ) : (
            <h4 className="text-sm font-medium text-gray-800 dark:text-white truncate">
              {card.name}
            </h4>
          )}
          {card.description && !isEditing && (
            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
              {card.description}
            </p>
          )}
        </div>

        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button
            onClick={(e) => {
              e.stopPropagation()
              onRemove()
            }}
            className="p-1.5 rounded-lg hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400 bg-white/50 dark:bg-gray-800/50 backdrop-blur-sm shadow-sm border border-red-200 dark:border-red-900/50"
            title="删除"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      <div className="mt-2 text-xs text-gray-400 dark:text-gray-500">
        添加于 {new Date(card.createdAt).toLocaleDateString()}
      </div>

      {/* Preview Tooltip */}
      {showPreview && createPortal(
        <NodeCardPreview
          card={parseCardContent()}
          position={previewPosition}
        />,
        document.body
      )}
    </div>
  )
}

// Node Card Preview Component
interface NodeCardPreviewProps {
  card: {
    type: string
    title: string
    content: string
    imageUrl: string | null
    color: string
  }
  position: { x: number; y: number }
}

function NodeCardPreview({ card, position }: NodeCardPreviewProps) {
  const previewRef = useRef<HTMLDivElement>(null)
  const [offset, setOffset] = useState({ x: -8, y: 0 })
  const [isVisible, setIsVisible] = useState(false)

  // Use layout effect to calculate boundary adjustments before paint
  useLayoutEffect(() => {
    if (previewRef.current) {
      const rect = previewRef.current.getBoundingClientRect()
      const viewportHeight = window.innerHeight

      let adjX = -8
      let adjY = 0

      // Prevent overflow from left side
      if (rect.left < 10) {
        adjX += (10 - rect.left)
      }

      // Prevent overflow from bottom
      if (rect.bottom > viewportHeight - 10) {
        adjY -= (rect.bottom - (viewportHeight - 10))
      }

      // Prevent overflow from top
      if (rect.top < 10) {
        adjY += (10 - rect.top)
      }

      setOffset({ x: adjX, y: adjY })
      setIsVisible(true)
    }
  }, [position.x, position.y])

  return (
    <div
      ref={previewRef}
      className="fixed z-[9999] pointer-events-none"
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
        transform: `translateX(-100%) translate(${offset.x}px, ${offset.y}px)`,
        maxWidth: '430px',
        maxHeight: '500px',
        opacity: isVisible ? 1 : 0,
      }}
    >
      <div className="animate-in fade-in duration-200">
        <div
          className="rounded-lg shadow-2xl border border-gray-300 dark:border-gray-600 overflow-hidden bg-white dark:bg-gray-800 relative"
          style={{
            minWidth: '250px',
            backgroundColor: card.color || '#ffffff'
          }}
        >
          {/* Arrow pointing to the panel */}
          <div
            className="absolute top-6 -right-2 w-0 h-0 border-l-8 border-l-gray-300 dark:border-l-gray-600 border-t-8 border-t-transparent border-b-8 border-b-transparent"
            style={{ transform: `translateY(${-offset.y}px)` }}
          />
          <div
            className="absolute top-[23px] -right-[7px] w-0 h-0 border-l-[7px] border-l-white dark:border-l-gray-800 border-t-[7px] border-t-transparent border-b-[7px] border-b-transparent"
            style={{ transform: `translateY(${-offset.y}px)` }}
          />

          {/* Header */}
          <div className="px-4 py-2 border-b border-gray-200 dark:border-gray-700 bg-white/50 dark:bg-gray-800/50 backdrop-blur-sm">
            <div className="flex items-center gap-2">
              <span className={`text-xs px-2 py-0.5 rounded ${card.type === 'image'
                ? 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400'
                : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                }`}>
                {card.type === 'image' ? '图片节点' : '文本节点'}
              </span>
              <h5 className="text-sm font-semibold text-gray-800 dark:text-white truncate flex-1">
                {card.title}
              </h5>
            </div>
          </div>

          {/* Content */}
          <div className="p-4">
            {card.type === 'image' && card.imageUrl ? (
              <div className="space-y-3">
                <div className="relative rounded-lg overflow-hidden bg-gray-100 dark:bg-gray-900 border border-gray-200 dark:border-gray-700">
                  <img
                    src={card.imageUrl}
                    alt={card.title}
                    className="w-full h-auto max-h-64 object-contain"
                  />
                </div>
                {card.content && (
                  <div className="text-sm text-gray-600 dark:text-gray-400 line-clamp-3">
                    {card.content}
                  </div>
                )}
              </div>
            ) : (
              <div className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap break-words max-h-64 overflow-y-auto custom-scrollbar">
                {card.content || <span className="text-gray-400 italic">暂无内容</span>}
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="px-4 py-2 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50">
            <div className="flex items-center justify-between text-xs text-gray-500 dark:text-gray-400">
              <span>双击使用此节点</span>
              <span>点击拖拽到画布</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
